/**
 * Provenance of harvests, derived only from the strategy's own completed action history (strategy-neutral).
 *
 * A harvest is "attributable" only if the same strategy completed a plantField on that field before the
 * harvest started and no harvest of that field happened in between. Any other harvest is reported as
 * "not planted by the strategy": in the `established` scenario that is crop that already stood in the initial
 * state, but the agent API cannot distinguish that from other unknown provenance, so it is never counted as
 * production generated by the strategy. Sales draw from a fungible per-product inventory, so realized revenue
 * is NOT split by provenance (it would require an assumption such as FIFO); it is reported in aggregate only.
 */
export interface AttributionAction {
  type: string;
  params: Record<string, unknown>;
  status: string;
  startedAtS: number | null;
  finishedAtS: number | null;
  measurements: Record<string, number>;
}

export interface HarvestProvenance {
  fieldId: string;
  harvestedAtDay: number | null;
  grainKg: number;
  hayKg: number;
  provenance: "planted_by_strategy" | "not_planted_by_strategy";
  /** Crop is known only when the strategy planted it. */
  crop: string | null;
}

export interface ProductionAttribution {
  harvests: HarvestProvenance[];
  plantedByStrategy: { harvests: number; grainKg: number; hayKg: number; grainKgByCrop: Record<string, number>; valueAtKnownPrices: number | null };
  notPlantedByStrategy: { harvests: number; grainKg: number; hayKg: number; note: string };
  plantings: number;
  revenueAttribution: "aggregate_only";
}

const round = (n: number, d = 2) => Math.round(n * 10 ** d) / 10 ** d;

export function attributeProduction(actions: AttributionAction[], marketPricesPerKg: Record<string, number> | null, dayS = 60): ProductionAttribution {
  const done = actions
    .filter((a) => a.status === "completed" && typeof a.params.fieldId === "string")
    .sort((a, b) => (a.startedAtS ?? 0) - (b.startedAtS ?? 0));
  const planted = new Map<string, { crop: string; finishedAtS: number }>();
  const harvests: HarvestProvenance[] = [];
  let plantings = 0;
  for (const a of done) {
    const fieldId = a.params.fieldId as string;
    if (a.type === "plantField" && typeof a.params.crop === "string") {
      planted.set(fieldId, { crop: a.params.crop, finishedAtS: a.finishedAtS ?? a.startedAtS ?? 0 });
      plantings += 1;
    } else if (a.type === "harvestField") {
      const prior = planted.get(fieldId);
      const own = prior !== undefined && prior.finishedAtS <= (a.startedAtS ?? Number.POSITIVE_INFINITY);
      planted.delete(fieldId);
      harvests.push({
        fieldId,
        harvestedAtDay: a.finishedAtS === null ? null : round(a.finishedAtS / dayS, 1),
        grainKg: round(a.measurements.grainKg ?? 0),
        hayKg: round(a.measurements.hayKg ?? 0),
        provenance: own ? "planted_by_strategy" : "not_planted_by_strategy",
        crop: own ? prior!.crop : null,
      });
    }
  }
  const own = harvests.filter((h) => h.provenance === "planted_by_strategy");
  const other = harvests.filter((h) => h.provenance === "not_planted_by_strategy");
  const grainKgByCrop: Record<string, number> = {};
  for (const h of own) grainKgByCrop[h.crop!] = round((grainKgByCrop[h.crop!] ?? 0) + h.grainKg);
  const priced = marketPricesPerKg !== null && Object.keys(grainKgByCrop).every((crop) => (marketPricesPerKg[crop] ?? 0) > 0);
  return {
    harvests,
    plantedByStrategy: {
      harvests: own.length,
      grainKg: round(own.reduce((s, h) => s + h.grainKg, 0)),
      hayKg: round(own.reduce((s, h) => s + h.hayKg, 0)),
      grainKgByCrop,
      valueAtKnownPrices: priced ? round(Object.entries(grainKgByCrop).reduce((s, [crop, kg]) => s + kg * marketPricesPerKg![crop]!, 0)) : null,
    },
    notPlantedByStrategy: {
      harvests: other.length,
      grainKg: round(other.reduce((s, h) => s + h.grainKg, 0)),
      hayKg: round(other.reduce((s, h) => s + h.hayKg, 0)),
      note: "Crop already standing in the initial scenario or of unknown provenance; not production generated by the strategy. Crop type is not observable.",
    },
    plantings,
    revenueAttribution: "aggregate_only",
  };
}
